@router.put("/devices/{device_uuid}/reassign-gateway")
async def reassign_device_gateway(
    device_uuid: str,
    payload: ReassignGatewayPayload,
    current_user: User = Depends(get_current_user)
):
    try:
        device = await SmartDevice.objects.get(
            device_uuid=device_uuid,
            facility_id=current_user.facility_id
        )
        new_gateway = await IoTGateway.objects.get(
            gateway_id=payload.gateway_id,
            facility_id=current_user.facility_id
        )
    except ormar.NoMatch:
        raise HTTPException(status_code=404, detail="Device or Gateway not found in your facility")

    device.gateway = new_gateway
    await device.update()
    return {"status": "reassigned", "device_uuid": device_uuid, "gateway_id": payload.gateway_id}
